begin;
create schema domain_launch_test;
create function domain_launch_test.ok(condition boolean,message text) returns void language plpgsql as $$ begin if not coalesce(condition,false) then raise exception 'DOMAIN LAUNCH ASSERTION FAILED: %',message; end if;raise notice 'ok - domain launch: %',message;end; $$;
create function domain_launch_test.fails(statement text,message text) returns void language plpgsql as $$ begin begin execute statement; exception when others then raise notice 'ok - domain launch: % (refused)',message;return;end;raise exception 'DOMAIN LAUNCH ASSERTION FAILED: %',message;end; $$;
grant usage on schema domain_launch_test to anon,authenticated,service_role;
grant execute on all functions in schema domain_launch_test to anon,authenticated,service_role;
insert into auth.users(id,email) values('ad100000-0000-0000-0000-000000000001','reserve-owner@example.test');
insert into auth.users(id,email) values('ad100000-0000-0000-0000-000000000002','launch-staff@example.test');
insert into public.staff_members(user_id,role) values('ad100000-0000-0000-0000-000000000002','admin');
insert into public.organizations(id,name,slug) values('ad200000-0000-0000-0000-000000000001','Reserve tests','domain-launch-tests');
insert into public.organization_members(organization_id,user_id,role) values('ad200000-0000-0000-0000-000000000001','ad100000-0000-0000-0000-000000000001','owner');
insert into public.websites(id,organization_id,name) values('ad300000-0000-0000-0000-000000000001','ad200000-0000-0000-0000-000000000001','Reserve website');
insert into vigil.domain_launch_profiles(id,registrar_scope,stripe_account,max_registrar_minor,max_client_minor,service_fee_minor,allowed_country,terms_version,terms_url,registration_agreement_url,renewal_policy_version,retention_days,purchasing_enabled,tax_code,fee_tax_code,tax_review_reference,supplier_tax_reference,approval_reference,approved_by,valid_until,allowed_regions,reserve_service_fee,supplier_tax_allowance_minor,dns_approved)
 values('ad400000-0000-0000-0000-000000000001','namecom:live:'||repeat('a',64),'acct_fixture',2000,3000,500,'US','domain-v1','https://example.test/terms','https://www.name.com/policies/registration-agreement','manual-v1',2557,true,'txcd_20030000','txcd_20030000','fixture NY review','fixture bounded supplier review','fixture approval only','ad100000-0000-0000-0000-000000000001',now()+interval '1 day',array['NY'],true,500,true);
select set_config('request.jwt.claims','{"role":"service_role"}',true);
set local role service_role;
do $$
declare p jsonb;q uuid;final_q uuid;o uuid;asset uuid;d jsonb;dns_plan jsonb;plan_id uuid;scope text:='namecom:live:'||repeat('a',64);
 org uuid:='ad200000-0000-0000-0000-000000000001';site uuid:='ad300000-0000-0000-0000-000000000001';owner_id uuid:='ad100000-0000-0000-0000-000000000001';
begin
 p:=public.ensure_domain_website_policy(org,site,owner_id,'ad400000-0000-0000-0000-000000000001');
 q:=public.create_live_domain_quote(org,site,'launch-fixture.com',1200,1400,now()+interval '5 minutes');
 final_q:=public.create_taxed_domain_quote(q,org,owner_id,'taxcalc_launch',repeat('a',64),0,1700,now()+interval '1 hour','acct_fixture','[]','NY');
 o:=public.create_domain_purchase(final_q,org,owner_id,gen_random_uuid(),gen_random_uuid(),repeat('x',100),repeat('a',64),1700,'usd',false,'domain-v1','manual-v1');
 perform domain_launch_test.fails(format('select public.authorize_managed_domain_launch(%L,%L,%L)',o,org,'ad100000-0000-0000-0000-000000000002'),'staff cannot impersonate the purchasing owner');
 perform domain_launch_test.ok(not (public.managed_domain_handoff_status(o,org)->>'automaticConnection')::boolean,'old purchase has no implicit automatic connection permission');
 perform public.authorize_managed_domain_launch(o,org,owner_id);
 perform public.authorize_managed_domain_launch(o,org,owner_id);
 perform domain_launch_test.ok((select count(*)=1 from vigil.managed_domain_launch_authorizations where order_id=o),'connection consent is scoped and idempotent');
 update public.domain_orders set registration_state='submitting',payment_state='authorized' where id=o;
 d:=jsonb_build_object('fqdn','launch-fixture.com','status','registered','contactVerification','pending','expiresAt',now()+interval '1 year','autoRenew',false,'supplierReceipt',jsonb_build_object('baseMinor',1200,'taxMinor',120,'totalMinor',1320));
 insert into public.provider_links(provider,resource_kind,external_id,entity_type,entity_id,metadata) values('other','registrar_order',scope||':order:123','domain_order',o,jsonb_build_object('environment','live','account_scope',scope));
 asset:=public.record_live_domain_registration(o,d,scope||':domain:launch-fixture.com',scope);
 update public.domain_orders set payment_state='paid' where id=o;
 perform domain_launch_test.ok(public.managed_domain_launch_context(asset,org,site) is null,'paid but unverified domain cannot connect at launch');
 perform domain_launch_test.ok(not (public.managed_domain_handoff_status(o,org)->>'staffNotified')::boolean,'no ready alert before owner verification');
 perform public.sync_managed_domain_state(asset,jsonb_build_object('fqdn','launch-fixture.com','status','registered','contactVerification','verified','expiresAt',now()+interval '1 year','autoRenew',false),scope||':domain:launch-fixture.com',scope,now());
 perform domain_launch_test.ok(public.managed_domain_launch_context(asset,org,site)->>'ownerId'=owner_id::text,'verified paid domain retains saved owner connection permission');
 perform domain_launch_test.ok(public.managed_domain_launch_context(asset,gen_random_uuid(),site) is null and public.managed_domain_launch_context(asset,org,gen_random_uuid()) is null,'connection permission cannot cross organization or website');
 update public.domain_registrations set contact_verification='verified' where id=asset;
 update public.domain_orders set payment_state='paid' where id=o;
 perform domain_launch_test.ok((select count(*)=1 from public.provisioning_jobs where idempotency_key='domain.registration.ready:'||asset::text),'repeated payment and verification create one email outbox job');
 perform domain_launch_test.ok((select count(*)=1 from public.notifications where organization_id=org and kind='domain.ready_for_launch' and user_id='ad100000-0000-0000-0000-000000000002'),'staff receives one inbox notification');
 perform domain_launch_test.ok((select status<>'live' and live_url is null and primary_domain_id is null from public.websites where id=site),'email verification cannot publish or approve the website');
 perform domain_launch_test.ok((select count(*)=0 from public.deployments where website_id=site) and (select count(*)=0 from public.domains where managed_registration_id=asset),'domain readiness cannot deploy or apply DNS');
 perform public.bind_live_managed_domain(asset,site,owner_id);
 dns_plan:=jsonb_build_object('fqdn','launch-fixture.com','accountScope',scope,'snapshotDigest',repeat('a',64),'expected',jsonb_build_array(jsonb_build_object('type','A','name','@','value','76.76.21.21','ttl',300)),'creates','[]'::jsonb);
 p:=public.create_managed_launch_dns_plan(asset,owner_id,dns_plan,o);
 plan_id:=(p->>'id')::uuid;
 perform public.claim_managed_dns_plan_environment(plan_id,org,owner_id,'live');
 perform public.authorize_live_domain_dns(asset,dns_plan,scope);
 perform domain_launch_test.ok((select launch_authorization_order_id=o from vigil.managed_domain_dns_plans where id=plan_id),'exact DNS plan retains its durable scoped launch permission');
 update vigil.managed_domain_launch_authorizations set revoked_at=now() where order_id=o;
 perform domain_launch_test.ok(public.managed_domain_launch_context(asset,org,site) is null,'revoked connection permission blocks automatic launch connection');
 perform domain_launch_test.fails(format('select public.authorize_live_domain_dns(%L,%L,%L)',asset,dns_plan,scope),'revocation also blocks the exact registrar write boundary');
 perform domain_launch_test.fails(format('select public.authorize_managed_domain_launch(%L,%L,%L)',o,org,owner_id),'retry cannot restore revoked consent');
 -- Reverse delivery order: registrar verification arrives before payment capture.
 site:=gen_random_uuid();
 insert into public.websites(id,organization_id,name) values(site,org,'Second launch fixture');
 p:=public.ensure_domain_website_policy(org,site,owner_id,'ad400000-0000-0000-0000-000000000001');
 q:=public.create_live_domain_quote(org,site,'second-launch-fixture.com',1200,1400,now()+interval '5 minutes');
 final_q:=public.create_taxed_domain_quote(q,org,owner_id,'taxcalc_launch_second',repeat('b',64),0,1700,now()+interval '1 hour','acct_fixture','[]','NY');
 o:=public.create_domain_purchase(final_q,org,owner_id,gen_random_uuid(),gen_random_uuid(),repeat('x',100),repeat('a',64),1700,'usd',false,'domain-v1','manual-v1');
 update public.domain_orders set registration_state='submitting',payment_state='authorized' where id=o;
 insert into public.provider_links(provider,resource_kind,external_id,entity_type,entity_id,metadata) values('other','registrar_order',scope||':order:124','domain_order',o,jsonb_build_object('environment','live','account_scope',scope));
 d:=jsonb_set(jsonb_set(d,'{fqdn}','"second-launch-fixture.com"'),'{contactVerification}','"verified"');
 asset:=public.record_live_domain_registration(o,d,scope||':domain:second-launch-fixture.com',scope);
 perform domain_launch_test.ok(not (public.managed_domain_handoff_status(o,org)->>'staffNotified')::boolean,'verified email does not announce a failed or pending capture');
 update public.domain_orders set payment_state='paid' where id=o;
 perform domain_launch_test.ok((public.managed_domain_handoff_status(o,org)->>'staffNotified')::boolean,'later payment still queues the verified-domain admin handoff');

end;$$;
reset role;
select set_config('request.jwt.claims','{"role":"authenticated","sub":"ad100000-0000-0000-0000-000000000001"}',true);
set local role authenticated;
select domain_launch_test.fails('select * from vigil.managed_domain_launch_authorizations','client cannot forge connection permission');
select domain_launch_test.ok(not has_function_privilege('authenticated','public.authorize_managed_domain_launch(uuid,uuid,uuid)','EXECUTE'),'consent is only recorded through the authenticated owner API');
select domain_launch_test.ok(not has_function_privilege('authenticated','public.managed_domain_launch_context(uuid,uuid,uuid)','EXECUTE'),'customer cannot execute admin launch context');
select domain_launch_test.ok((select count(*)=0 from public.notifications where kind='domain.ready_for_launch'),'customer cannot read staff readiness alerts');
reset role;
rollback;
